package opencode

import (
	"fmt"
	"strconv"
	"strings"
	"time"

	"github.com/Antonio7098/agentwrap"
)

type projectionInput struct {
	runID  agentwrap.RunID
	turnID agentwrap.TurnID
	ctx    agentwrap.RuntimeContext
	seq    int64
	now    time.Time
	record nativeRecord
}

type projectionResult struct {
	event            agentwrap.Event
	final            bool
	idle             bool
	usage            agentwrap.Usage
	artifacts        []agentwrap.ArtifactRef
	warnings         []string
	fatal            *agentwrap.SDKError
	rateLimit        *agentwrap.RateLimitInfo
	finishReason     string
	terminalEvidence string
}

func projectNative(in projectionInput) projectionResult {
	record := in.record
	category, typ := classify(record)
	finishReason := finishReasonFrom(record.Data)
	nativeType := strings.TrimSpace(record.Type)
	idle := isSessionIdleStatus(record)
	terminalEvidence := ""
	if nativeType == "step_finish" {
		if isTerminalFinish(finishReason) {
			category = agentwrap.EventFinalResult
			terminalEvidence = "step_finish"
		} else {
			category = agentwrap.EventProgress
		}
	} else if idle {
		terminalEvidence = "session.status.idle"
	}
	payload := agentwrap.EventPayload{}
	for k, v := range record.Data {
		if k == "type" || k == "timestamp" {
			continue
		}
		payload[k] = v
	}
	payload["native_type"] = record.Type
	payload["line"] = record.Line
	payload["turn_id"] = string(in.turnID)
	payload["context"] = in.ctx
	if finishReason != "" {
		payload["finish_reason"] = finishReason
	}
	if category == agentwrap.EventTool {
		payload = agentwrap.EventPayloadWithToolObservation(payload, toolObservationFrom(record.Data))
	}
	event := agentwrap.Event{
		ID:        agentwrap.EventID(fmt.Sprintf("%s:%d", in.runID, in.seq)),
		RunID:     in.runID,
		SessionID: firstSessionID(agentwrap.SessionID(record.SessionID), agentwrap.SessionID(stringValue(record.Data["sessionID"])), agentwrap.SessionID(propertiesStringValue(record.Data, "sessionID"))),
		Time:      eventTime(record.Timestamp, in.now),
		Type:      typ,
		Payload:   agentwrap.EventPayloadWithKind(category, payload),
		Raw: &agentwrap.RawPayload{
			Source:   "opencode.stdout",
			Encoding: "json",
			Data:     append([]byte(nil), record.Raw...),
			Safe:     false,
		},
	}
	if event.SessionID == "" {
		event.SessionID = agentwrap.SessionID(stringValue(record.Data["session_id"]))
	}
	result := projectionResult{event: event, idle: idle, finishReason: finishReason, terminalEvidence: terminalEvidence}
	if category == agentwrap.EventFinalResult {
		result.final = true
	}
	if category == agentwrap.EventUsage {
		result.usage = usageFrom(record.Data)
	}
	if category == agentwrap.EventArtifact {
		result.artifacts = artifactsFrom(record.Data)
	}
	if category == agentwrap.EventWarning {
		if msg := messageFrom(record.Data); msg != "" {
			result.warnings = append(result.warnings, msg)
		}
	}
	if category == agentwrap.EventFatalError {
		result.final = true
		if classified := classifyRateLimitData("opencode event", record.Data, in.ctx); classified != nil {
			result.fatal = classified.err
			result.rateLimit = classified.info
			event.Payload["rate_limit"] = classified.info
		} else {
			result.fatal = classifyFatalEventError(record.Data, in.ctx)
		}
	}
	return result
}

func toolObservationFrom(data map[string]any) agentwrap.ToolObservation {
	status := firstNestedString(data, "tool_status", "status", "phase")
	if status == "" {
		status = firstNestedString(data, "state")
	}
	return agentwrap.ToolObservation{
		CallID:    firstNestedString(data, "call_id", "callID", "tool_call_id", "toolCallId", "id"),
		Name:      firstNestedString(data, "tool", "name", "tool_name", "toolName"),
		Status:    status,
		Arguments: firstNestedValue(data, "arguments", "args", "input", "parameters"),
		Result:    firstNestedValue(data, "result", "output", "content"),
		Error:     firstNestedValue(data, "error"),
	}
}

func firstNestedString(value any, keys ...string) string {
	found := firstNestedValue(value, keys...)
	text, _ := found.(string)
	return strings.TrimSpace(text)
}

func firstNestedValue(value any, keys ...string) any {
	return nestedValue(value, keys, 0)
}

func nestedValue(value any, keys []string, depth int) any {
	if depth > 5 {
		return nil
	}
	switch typed := value.(type) {
	case map[string]any:
		for _, key := range keys {
			if found, ok := typed[key]; ok && found != nil {
				return found
			}
		}
		for _, nested := range typed {
			if found := nestedValue(nested, keys, depth+1); found != nil {
				return found
			}
		}
	case []any:
		for _, nested := range typed {
			if found := nestedValue(nested, keys, depth+1); found != nil {
				return found
			}
		}
	}
	return nil
}

func finishReasonFrom(data map[string]any) string {
	for _, key := range []string{"finish_reason", "finishReason", "stopReason", "stop_reason", "reason", "finish"} {
		if value := stringValue(data[key]); value != "" {
			return value
		}
	}
	if part, ok := data["part"].(map[string]any); ok {
		for _, key := range []string{"finish_reason", "finishReason", "stopReason", "stop_reason", "reason", "finish"} {
			if value := stringValue(part[key]); value != "" {
				return value
			}
		}
	}
	return ""
}

func isTerminalFinish(reason string) bool {
	switch strings.ToLower(strings.TrimSpace(reason)) {
	case "", "stop", "end_turn", "end-turn", "stop_sequence", "stop-sequence", "complete", "completed":
		return true
	case "tool_calls", "tool-calls", "tool_call", "tool-call", "tool", "max_tokens", "max-tokens", "length", "content_filter", "content-filter":
		return false
	default:
		return false
	}
}

func isSessionIdleStatus(record nativeRecord) bool {
	if strings.TrimSpace(record.Type) != "session.status" {
		return false
	}
	if strings.EqualFold(stringValue(record.Data["status"]), "idle") {
		return true
	}
	if status, ok := record.Data["status"].(map[string]any); ok {
		return strings.EqualFold(stringValue(status["type"]), "idle")
	}
	if properties, ok := record.Data["properties"].(map[string]any); ok {
		if strings.EqualFold(stringValue(properties["status"]), "idle") {
			return true
		}
		if status, ok := properties["status"].(map[string]any); ok {
			return strings.EqualFold(stringValue(status["type"]), "idle")
		}
	}
	return false
}

func classifyFatalEventError(data map[string]any, ctx agentwrap.RuntimeContext) *agentwrap.SDKError {
	message := messageFrom(data)
	normalized := strings.ToLower(message)
	switch {
	case strings.Contains(normalized, "model not found") || strings.Contains(normalized, "unknown model"):
		return agentwrap.NewError(agentwrap.ErrorModelUnavailable, "opencode event", "OpenCode model is unavailable", nil, agentwrap.WithDebugDetail(message), agentwrap.WithProviderModel(ctx.Provider, ctx.Model), agentwrap.WithRuntimeKind(ctx.RuntimeKind))
	case strings.Contains(normalized, "unauthorized") || strings.Contains(normalized, "authentication") || strings.Contains(normalized, "invalid api key") || strings.Contains(normalized, "api key"):
		return agentwrap.NewError(agentwrap.ErrorAuthentication, "opencode event", "OpenCode provider authentication failed", nil, agentwrap.WithDebugDetail(message), agentwrap.WithProviderModel(ctx.Provider, ctx.Model), agentwrap.WithRuntimeKind(ctx.RuntimeKind))
	default:
		return agentwrap.NewError(agentwrap.ErrorRuntimeExit, "opencode event", "OpenCode reported a fatal session error", nil, agentwrap.WithDebugDetail(message), agentwrap.WithProviderModel(ctx.Provider, ctx.Model), agentwrap.WithRuntimeKind(ctx.RuntimeKind))
	}
}

func classify(record nativeRecord) (agentwrap.EventKind, string) {
	nativeType := strings.TrimSpace(record.Type)
	switch nativeType {
	case "step_start":
		return agentwrap.EventProgress, nativeType
	case "step_finish":
		return agentwrap.EventFinalResult, nativeType
	case "text", "reasoning":
		return agentwrap.EventMessage, nativeType
	case "tool_use":
		return agentwrap.EventTool, nativeType
	case "error":
		return agentwrap.EventFatalError, nativeType
	}
	if strings.Contains(nativeType, "permission") {
		return agentwrap.EventPermission, nativeType
	}
	if strings.Contains(nativeType, "question") || strings.Contains(nativeType, "status") && strings.Contains(nativeType, "waiting") {
		return agentwrap.EventBlocking, nativeType
	}
	if strings.Contains(nativeType, "usage") || strings.Contains(nativeType, "token") || strings.Contains(nativeType, "cost") {
		return agentwrap.EventUsage, nativeType
	}
	if strings.Contains(nativeType, "artifact") || strings.Contains(nativeType, "file") {
		return agentwrap.EventArtifact, nativeType
	}
	if strings.Contains(nativeType, "warn") {
		return agentwrap.EventWarning, nativeType
	}
	if strings.Contains(nativeType, "session") {
		return agentwrap.EventSession, nativeType
	}
	return agentwrap.EventNativeExtension, nativeType
}

func eventTime(value any, fallback time.Time) time.Time {
	switch v := value.(type) {
	case float64:
		if v > 1e12 {
			return time.UnixMilli(int64(v))
		}
		return time.Unix(int64(v), 0)
	case string:
		if parsed, err := time.Parse(time.RFC3339Nano, v); err == nil {
			return parsed
		}
		if n, err := strconv.ParseInt(v, 10, 64); err == nil {
			if n > 1e12 {
				return time.UnixMilli(n)
			}
			return time.Unix(n, 0)
		}
	}
	return fallback
}

func firstSessionID(values ...agentwrap.SessionID) agentwrap.SessionID {
	for _, value := range values {
		if value != "" {
			return value
		}
	}
	return ""
}

func stringValue(value any) string {
	s, _ := value.(string)
	return s
}

func propertiesStringValue(data map[string]any, key string) string {
	properties, ok := data["properties"].(map[string]any)
	if !ok {
		return ""
	}
	return stringValue(properties[key])
}

func messageFrom(data map[string]any) string {
	for _, key := range []string{"message", "error"} {
		if value := stringValue(data[key]); value != "" {
			return value
		}
	}
	if errObj, ok := data["error"].(map[string]any); ok {
		if dataObj, ok := errObj["data"].(map[string]any); ok {
			return stringValue(dataObj["message"])
		}
		return stringValue(errObj["message"])
	}
	return ""
}

func usageFrom(data map[string]any) agentwrap.Usage {
	usage := agentwrap.Usage{Native: data}
	if n, ok := int64From(data["input_tokens"]); ok {
		usage.InputTokens = &n
	}
	if n, ok := int64From(data["output_tokens"]); ok {
		usage.OutputTokens = &n
	}
	if n, ok := int64From(data["total_tokens"]); ok {
		usage.TotalTokens = &n
	}
	return usage
}

func int64From(value any) (int64, bool) {
	switch v := value.(type) {
	case float64:
		return int64(v), true
	case int64:
		return v, true
	case int:
		return int64(v), true
	default:
		return 0, false
	}
}

func artifactsFrom(data map[string]any) []agentwrap.ArtifactRef {
	uri := stringValue(data["uri"])
	if uri == "" {
		uri = stringValue(data["path"])
	}
	if uri == "" {
		return nil
	}
	return []agentwrap.ArtifactRef{{
		URI:         uri,
		Kind:        stringValue(data["kind"]),
		Description: stringValue(data["description"]),
	}}
}

package sprint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"time"

	pruntime "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
	"github.com/Antonio7098/ultraplan-go/internal/project"
)

const (
	runtimeMetricsSchemaVersion = 1
	runtimeMetricsFileName      = ".runtime-metrics.json"
	maxRuntimeMetricRecords     = 512
)

type RuntimeTokenMetric struct {
	Known bool  `json:"known"`
	Value int64 `json:"value,omitempty"`
}

type SprintRuntimeMetric struct {
	Stage              PlanningStage      `json:"stage"`
	Operation          string             `json:"operation,omitempty"`
	Task               string             `json:"task,omitempty"`
	Coverage           string             `json:"coverage,omitempty"`
	RunID              string             `json:"run_id,omitempty"`
	SessionID          string             `json:"session_id,omitempty"`
	Status             string             `json:"status,omitempty"`
	Provider           string             `json:"provider,omitempty"`
	Model              string             `json:"model,omitempty"`
	PromptBytes        int                `json:"prompt_bytes"`
	SharedPrefixBytes  int                `json:"shared_prefix_bytes,omitempty"`
	StageSuffixBytes   int                `json:"stage_suffix_bytes"`
	SharedPrefixDigest string             `json:"shared_prefix_sha256,omitempty"`
	CacheKey           string             `json:"cache_key,omitempty"`
	InputTokens        RuntimeTokenMetric `json:"input_tokens"`
	OutputTokens       RuntimeTokenMetric `json:"output_tokens"`
	ReasoningTokens    RuntimeTokenMetric `json:"reasoning_tokens"`
	CacheReadTokens    RuntimeTokenMetric `json:"cache_read_tokens"`
	CacheWriteTokens   RuntimeTokenMetric `json:"cache_write_tokens"`
	TotalTokens        RuntimeTokenMetric `json:"total_tokens"`
	Turns              RuntimeTokenMetric `json:"turns"`
	CostAmount         float64            `json:"cost_amount,omitempty"`
	CostCurrency       string             `json:"cost_currency,omitempty"`
	CostEstimated      bool               `json:"cost_estimated,omitempty"`
	CostSource         string             `json:"cost_source,omitempty"`
	StartedAt          time.Time          `json:"started_at,omitempty"`
	FinishedAt         time.Time          `json:"finished_at,omitempty"`
	ErrorCategory      string             `json:"error_category,omitempty"`
}

type SprintRuntimeMetrics struct {
	SchemaVersion int                   `json:"schema_version"`
	Project       string                `json:"project"`
	Sprint        string                `json:"sprint"`
	UpdatedAt     time.Time             `json:"updated_at"`
	Runs          []SprintRuntimeMetric `json:"runs"`
}

func RuntimeMetricsRelPath(sp Sprint) string {
	return filepath.ToSlash(filepath.Join("projects", sp.Project, "sprints", sp.Slug, runtimeMetricsFileName))
}

func LoadRuntimeMetrics(root string, sp Sprint) (SprintRuntimeMetrics, error) {
	path, err := resolveSprintContained(root, sp, RuntimeMetricsRelPath(sp))
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	var metrics SprintRuntimeMetrics
	if err := json.Unmarshal(data, &metrics); err != nil {
		return SprintRuntimeMetrics{}, fmt.Errorf("decode sprint runtime metrics: %w", err)
	}
	if metrics.SchemaVersion != runtimeMetricsSchemaVersion || metrics.Project != sp.Project || metrics.Sprint != sp.Slug {
		return SprintRuntimeMetrics{}, fmt.Errorf("invalid sprint runtime metrics identity")
	}
	return metrics, nil
}

func (s Service) RuntimeMetrics(projectRef, sprintRef string) (SprintRuntimeMetrics, error) {
	projects, err := project.DiscoverProjects(s.root)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	p, err := project.ResolveProject(projects, projectRef)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	sprints, err := DiscoverSprints(s.root, p)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	sp, err := ResolveSprint(sprints, sprintRef)
	if err != nil {
		return SprintRuntimeMetrics{}, err
	}
	if !inside(p.Path, sp.Path) {
		return SprintRuntimeMetrics{}, fmt.Errorf("sprint path mismatch for %q", sp.Slug)
	}
	metrics, err := LoadRuntimeMetrics(s.root, sp)
	if errors.Is(err, os.ErrNotExist) {
		return SprintRuntimeMetrics{SchemaVersion: runtimeMetricsSchemaVersion, Project: sp.Project, Sprint: sp.Slug}, nil
	}
	return metrics, err
}

func (s Service) startSprintRuntime(ctx context.Context, sp Sprint, stage PlanningStage, req pruntime.Request) (pruntime.Result, error) {
	// Retry cleanup that was interrupted by a crash before admitting more work.
	// Recent failed stores remain available for session recovery.
	pruntime.CleanupRuntimeStores(sp.Path, 72*time.Hour, 2*1024*1024*1024, false)
	result, runErr := s.runtime.StartRun(ctx, req)
	if metricErr := s.recordRuntimeMetric(sp, stage, req, result); metricErr != nil {
		result.Warnings = append(result.Warnings, "runtime metrics were not persisted: "+safeError(metricErr))
	}
	return result, runErr
}

func (s Service) recordRuntimeMetric(sp Sprint, stage PlanningStage, req pruntime.Request, result pruntime.Result) error {
	if s.metricsMu != nil {
		s.metricsMu.Lock()
		defer s.metricsMu.Unlock()
	}
	metrics, err := LoadRuntimeMetrics(s.root, sp)
	if errors.Is(err, os.ErrNotExist) {
		metrics = SprintRuntimeMetrics{SchemaVersion: runtimeMetricsSchemaVersion, Project: sp.Project, Sprint: sp.Slug}
	} else if err != nil {
		return err
	}
	explanation := explainComposedPrompt(req.Prompt)
	record := SprintRuntimeMetric{
		Stage: stage, Operation: req.Metadata["operation"], Task: req.Metadata["task"], Coverage: req.Metadata["coverage"],
		RunID: result.RunID, SessionID: result.SessionID, Status: result.Status, Provider: req.Provider, Model: req.Model,
		PromptBytes: explanation.TotalBytes, SharedPrefixBytes: explanation.SharedPrefixBytes, StageSuffixBytes: explanation.StageSuffixBytes,
		SharedPrefixDigest: explanation.SharedPrefixDigest, CacheKey: explanation.CacheKey,
		InputTokens: metricToken(result.Usage.InputTokensKnown, result.Usage.InputTokens), OutputTokens: metricToken(result.Usage.OutputTokensKnown, result.Usage.OutputTokens),
		ReasoningTokens: metricToken(result.Usage.ReasoningTokensKnown, result.Usage.ReasoningTokens), CacheReadTokens: metricToken(result.Usage.CacheReadTokensKnown, result.Usage.CacheReadTokens),
		CacheWriteTokens: metricToken(result.Usage.CacheWriteTokensKnown, result.Usage.CacheWriteTokens), TotalTokens: metricToken(result.Usage.TotalTokensKnown, result.Usage.TotalTokens),
		Turns: metricToken(result.Usage.TurnsKnown, result.Usage.Turns), StartedAt: result.StartedAt, FinishedAt: result.FinishedAt,
	}
	if result.EstimatedCost != nil {
		record.CostAmount, record.CostCurrency, record.CostEstimated = result.EstimatedCost.Amount, result.EstimatedCost.Currency, result.EstimatedCost.Estimate
		record.CostSource = result.EstimatedCost.Source
	}
	if result.Error != nil {
		record.ErrorCategory = result.Error.Category
	}
	metrics.Runs = append(metrics.Runs, record)
	if len(metrics.Runs) > maxRuntimeMetricRecords {
		metrics.Runs = append([]SprintRuntimeMetric(nil), metrics.Runs[len(metrics.Runs)-maxRuntimeMetricRecords:]...)
	}
	metrics.UpdatedAt = s.now().UTC()
	data, err := json.MarshalIndent(metrics, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	path, err := resolveSprintContained(s.root, sp, RuntimeMetricsRelPath(sp))
	if err != nil {
		return err
	}
	return atomicWriteFile(path, data)
}

func metricToken(known bool, value int64) RuntimeTokenMetric {
	return RuntimeTokenMetric{Known: known, Value: value}
}

package sprint

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
	"github.com/Antonio7098/ultraplan-go/internal/platform/gitpublish"
	"github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
)

type Runtime interface {
	StartRun(context.Context, runtime.Request) (runtime.Result, error)
}

type sessionDeleter interface {
	DeleteSession(context.Context, string) error
}

type runtimeStoreDeleter interface {
	DeleteRuntimeStore(context.Context, string) error
}

func (s Service) deleteCompletedSession(ctx context.Context, sessionID string) error {
	if strings.TrimSpace(sessionID) == "" {
		return nil
	}
	deleter, ok := s.runtime.(sessionDeleter)
	if !ok {
		return nil
	}
	return deleter.DeleteSession(ctx, sessionID)
}

func (s Service) deleteCompletedSessions(ctx context.Context, result runtime.Result) error {
	if result.RuntimeStorePath != "" {
		if deleter, ok := s.runtime.(runtimeStoreDeleter); ok {
			return deleter.DeleteRuntimeStore(ctx, result.RuntimeStorePath)
		}
	}
	ids := append([]string(nil), result.SessionIDs...)
	ids = append(ids, result.SessionID)
	seen := map[string]bool{}
	for _, id := range ids {
		if strings.TrimSpace(id) == "" || seen[id] {
			continue
		}
		seen[id] = true
		if err := s.deleteCompletedSession(ctx, id); err != nil {
			return err
		}
	}
	return nil
}

type FlowRequest struct {
	To              PlanningStage
	DryRun          bool
	ModelOverride   string
	VariantOverride string
	// StageOverrides optionally sets a per-stage runtime model and/or variant
	// for this flow invocation. Stages without an entry keep their configured
	// defaults unchanged.
	StageOverrides map[PlanningStage]StageRuntime
	Review         ReviewRequest
	Smoke          SmokeRequest
	Progress       func(FlowProgress)
}

type FlowProgress struct {
	Stage   PlanningStage
	State   string
	Message string
}

type FlowResult struct {
	Project      string
	Sprint       string
	To           PlanningStage
	DryRun       bool
	Message      string
	Runtime      runtime.Result
	Stages       []StageState
	Findings     []ValidationFinding
	Publications []gitpublish.Result
}

// Flow owns the ordered sprint state machine. Surfaces map requests and render
// this result; they do not schedule stages or duplicate verification policy.
func (s Service) Flow(ctx context.Context, projectRef, sprintRef string, req FlowRequest) (FlowResult, error) {
	stages, err := flowStages(req.To)
	if err != nil {
		return FlowResult{}, err
	}
	if req.DryRun {
		if req.To == StageReview || req.To == StageSmoke {
			verified, verifyErr := s.Verify(ctx, projectRef, sprintRef, VerifyRequest{To: req.To, DryRun: true, Review: req.Review, Smoke: req.Smoke, Progress: req.Progress})
			message := "verification dry run"
			if verified.ReviewResult != nil {
				message = firstNonEmptyString(verified.ReviewResult.Prompt, verified.ReviewResult.Message, message)
			}
			return FlowResult{Project: verified.Project, Sprint: verified.Sprint, To: req.To, DryRun: true, Message: message}, verifyErr
		}
		stages = []PlanningStage{req.To}
	} else {
		// A non-dry flow is the materialization entrypoint for a roadmap sprint.
		// Create its safe skeleton before acquiring the sprint-scoped mutation
		// lease; lease resolution deliberately accepts existing sprints only.
		sp, _, _, resolveErr := s.resolveSprintForRequirements(projectRef, sprintRef, true)
		if resolveErr != nil {
			return FlowResult{}, resolveErr
		}
		sprintRef = sp.Slug
		var release func()
		ctx, release, err = s.acquireMutationContext(ctx, projectRef, sprintRef)
		if err != nil {
			return FlowResult{}, err
		}

