	runtime.mu.Lock()
	defer runtime.mu.Unlock()
	if len(runtime.calls) != 3 {
		t.Fatalf("runtime calls=%d want 3", len(runtime.calls))
	}
	last := runtime.calls[2]
	if last.SessionID == "" || last.SessionAction != "continue" {
